corpus_block("test-stat-function.R: uses scale limits, not data limits", {
  dat <- data_frame(x = c(0.1, 1:100))
  dat$y <- dexp(dat$x)
  .plot("test-stat-function.R: uses scale limits, not data limits #1", base <- ggplot(dat, aes(x, y)) +
      stat_function(fun = dexp))
  .plot("test-stat-function.R: uses scale limits, not data limits #2", full <- base +
      scale_x_continuous(limits = c(0.1, 100)) +
      scale_y_continuous())
  ret <- get_layer_data(full)
  .plot("test-stat-function.R: uses scale limits, not data limits #3", full_log <- base +
      scale_x_log10(limits = c(0.1, 100)) +
      scale_y_continuous())
  ret_log <- get_layer_data(full_log)
})

